/**
 * MosaicMatchInput — autocomplete carrying a match state
 *
 * Composes MosaicCombobox (no autocomplete re-implementation) and adds a
 * match-state indicator. `matchState` and `stateLabels` are REQUIRED
 * props: the four match states are match semantics, never business
 * logic, and the host owns every label — no English fallback.
 *
 * data-slot="match-input" on the wrapper div.
 */

import {
  MosaicCombobox,
  type MosaicComboboxItem,
  type MosaicComboboxProps,
} from "@/components/ui/MosaicCombobox";
import { matchStateSignal, matchStateVariants } from "./match-input-variants.js";

// ── Utility ───────────────────────────────────────────────────────────────────

function cn(...classes: (string | undefined | null | false)[]): string {
  return classes.filter(Boolean).join(" ");
}

// ── Types ─────────────────────────────────────────────────────────────────────

export type MosaicMatchInputState = "exact" | "partial" | "ambiguous" | "none";

export interface MosaicMatchInputStateLabels {
  exact: string;
  partial: string;
  ambiguous: string;
  none: string;
}

export interface MosaicMatchInputProps extends Omit<MosaicComboboxProps, "disabled" | "className"> {
  /** Required — the four match states are match semantics, never inferred. */
  matchState: MosaicMatchInputState;
  /** Required — the host owns every label, no default copy is generated. */
  stateLabels: MosaicMatchInputStateLabels;
  /** Locked mode: the input becomes read-only/disabled. */
  locked?: boolean;
  className?: string;
}

export type { MosaicComboboxItem };

// ── Component ─────────────────────────────────────────────────────────────────

/**
 * MosaicMatchInput — combobox + match-state indicator.
 *
 * @example
 * <MosaicMatchInput
 *   items={items}
 *   matchState="ambiguous"
 *   stateLabels={{
 *     exact: t('MatchInput.exact'),
 *     partial: t('MatchInput.partial'),
 *     ambiguous: t('MatchInput.ambiguous'),
 *     none: t('MatchInput.none'),
 *   }}
 *   emptyMessage={t('MatchInput.empty')}
 * />
 */
export function MosaicMatchInput({
  matchState,
  stateLabels,
  locked,
  className,
  ...comboboxProps
}: MosaicMatchInputProps) {
  const { role, ariaLive } = matchStateSignal(matchState);
  const label = stateLabels[matchState];

  return (
    <div data-slot="match-input" className={cn("flex flex-col gap-1", className)}>
      <MosaicCombobox {...comboboxProps} disabled={locked} />
      <span
        role={role}
        aria-live={ariaLive}
        data-match-state={matchState}
        className={matchStateVariants({ matchState })}
      >
        {label}
      </span>
    </div>
  );
}

MosaicMatchInput.displayName = "MosaicMatchInput";

/**
 * matchStateVariants — pure CVA variant function for the match-state
 * indicator rendered by MosaicMatchInput.
 *
 * Each match state maps to a distinct visual + accessible signal so the
 * four states are mutually distinguishable BY THE COMPONENT, independent
 * of whatever label text the host passes in
 * (see MosaicMatchInput.test.tsx negative-pole tests, which pass an
 * IDENTICAL label for all four states on purpose).
 *
 * Zero browser / React runtime dependencies — safe in RSC / Node.js.
 */

import { cva } from "class-variance-authority";

export const matchStateVariants = cva(["text-xs font-medium"], {
  variants: {
    matchState: {
      exact: "text-success-700",
      partial: "text-warning-700",
      ambiguous: "text-warning-700",
      none: "text-destructive",
    },
  },
  defaultVariants: {
    matchState: "none",
  },
});

export type MosaicMatchInputMatchState = "exact" | "partial" | "ambiguous" | "none";

export interface MatchStateSignal {
  role: "status" | "alert";
  ariaLive: "off" | "polite" | "assertive";
}

/**
 * Accessible (role, aria-live) pair per match state. Every one of the four
 * states carries a DIFFERENT pair, so any two states are distinguishable
 * from each other purely from these DOM attributes — never from the
 * label text, which the host controls and must not be relied upon.
 *
 * - exact:     status / off       — resolved, nothing to announce
 * - partial:   status / polite     — informational, low urgency
 * - ambiguous: alert  / assertive  — the dangerous state: a wrong
 *              candidate could be silently accepted, so it is the MOST
 *              urgent signal, distinct from both "partial" (role) and
 *              "none" (aria-live)
 * - none:      alert  / polite     — terminal, no decision pending, so
 *              alert without the assertive urgency of "ambiguous"
 */
export function matchStateSignal(matchState: MosaicMatchInputMatchState): MatchStateSignal {
  switch (matchState) {
    case "exact":
      return { role: "status", ariaLive: "off" };
    case "partial":
      return { role: "status", ariaLive: "polite" };
    case "ambiguous":
      return { role: "alert", ariaLive: "assertive" };
    case "none":
      return { role: "alert", ariaLive: "polite" };
  }
}
